{"path":"ErrorBoundary.tsx","content":"import { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (error: Error, reset: () => void) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    const { onError } = this.props;
    console.error("[ErrorBoundary] Uncaught error:", error);
    console.error("[ErrorBoundary] Component stack:", info.componentStack);
    onError?.(error, info);
  }

  reset = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (!error) return children;

    if (fallback) return fallback(error, this.reset);

    return (
      <div role="alert" style={{ padding: "1.5rem", border: "1px solid #f87171", borderRadius: "0.5rem", background: "#fef2f2", fontFamily: "sans-serif" }}>
        <h2 style={{ margin: "0 0 0.5rem", color: "#b91c1c" }}>Something went wrong</h2>
        <pre style={{ margin: "0 0 1rem", fontSize: "0.85rem", color: "#7f1d1d", whiteSpace: "pre-wrap", wordBreak: "break-word" }}>
          {error.message}
        </pre>
        <button
          onClick={this.reset}
          style={{ padding: "0.4rem 1rem", background: "#dc2626", color: "#fff", border: "none", borderRadius: "0.375rem", cursor: "pointer", fontSize: "0.9rem" }}
        >
          Retry
        </button>
      </div>
    );
  }
}
"}

Created `ErrorBoundary.tsx`. Usage:

```tsx
// Basic — built-in fallback UI
<ErrorBoundary>
  <MyComponent />
</ErrorBoundary>

// Custom fallback
<ErrorBoundary
  fallback={(error, reset) => (
    <div>
      <p>{error.message}</p>
      <button onClick={reset}>Try again</button>
    </div>
  )}
  onError={(error, info) => sendToSentry(error, info)}
>
  <MyComponent />
</ErrorBoundary>
```

Key design decisions:
- `reset` clears `error` state — React re-mounts children on next render
- `onError` prop for external logging (Sentry, Datadog, etc.); `console.error` fires regardless
- Custom `fallback` render prop receives both `error` and `reset`, so callers have full control
- Default UI uses inline styles — no CSS dependency
